using System;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace Azure.Core.Pipeline
{
    /// <summary>
    /// A converter for <see cref="ResponseError"/> that avoids reliance on the internal converter.
    /// </summary>
    internal class ResponseErrorConverter : JsonConverter<ResponseError>
    {
        public override ResponseError Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            using var document = JsonDocument.ParseValue(ref reader);
            var element = document.RootElement;

            // ResponseError may be wrapped in an "error" property
            if (element.TryGetProperty("error", out JsonElement errorElement))
            {
                element = errorElement;
            }

            string code = null;
            string message = null;

            if (element.TryGetProperty("code", out JsonElement codeElement))
            {
                code = codeElement.GetString();
            }
            if (element.TryGetProperty("message", out JsonElement messageElement))
            {
                message = messageElement.GetString();
            }

            return new ResponseError(code, message);
        }

        public override void Write(Utf8JsonWriter writer, ResponseError value, JsonSerializerOptions options)
        {
            writer.WriteStartObject();
            if (value.Code != null)
            {
                writer.WriteString("code"u8, value.Code);
            }
            if (value.Message != null)
            {
                writer.WriteString("message"u8, value.Message);
            }
            writer.WriteEndObject();
        }
    }
}

